//! Reading AAF objects, checked against what upstream `pyaaf2` reads.
//!
//! The manifests here were generated by opening the same two fixture files
//! with `pyaaf2` and walking the object tree from the root, recording each
//! object's path, class and every property it holds. A property's value is
//! recorded in whatever form its storage format gives: a name for a
//! reference, a key for a weak reference, a count for a collection, and a
//! length and content hash for inline data.

mod common;

use std::fs::File;

use aaf::property::{PropertyFormat, PropertyValue, RefKey};
use aaf::{AafFile, Object};

use common::{data_dir, describe_stream, read_objects_manifest};

fn open(name: &str) -> AafFile<File> {
    let path = data_dir().join(name);
    AafFile::open(File::open(&path).expect("fixture is readable")).expect("fixture opens")
}

/// Renders one object's properties the way the manifests record them.
fn describe(file: &mut AafFile<File>, object: &Object) -> String {
    let mut properties = object.properties().to_vec();
    properties.sort_by_key(|p| p.pid);

    properties
        .iter()
        .map(|property| {
            let value = match &property.value {
                PropertyValue::Data(bytes) => format!("d:{}", describe_stream(bytes)),
                PropertyValue::Stream { name } => format!("s:{name}"),
                PropertyValue::StrongRef { name } => format!("r:{name}"),
                PropertyValue::StrongRefVector { index_name } => {
                    let index = file.vector_index(object, property).expect("index reads");
                    format!("v:{index_name}:{}", index.local_keys.len())
                }
                PropertyValue::StrongRefSet { index_name } => {
                    let index = file.set_index(object, property).expect("index reads");
                    format!("t:{index_name}:{}:{}", index.entries.len(), index.key_pid)
                }
                PropertyValue::WeakRefArray { index_name } => {
                    let index = file.weak_ref_array(object, property).expect("index reads");
                    format!(
                        "a:{index_name}:{}:{}:{}",
                        index.keys.len(),
                        index.weakref_index,
                        index.key_pid
                    )
                }
                PropertyValue::WeakRef {
                    weakref_index,
                    key_pid,
                    key,
                } => {
                    let key = match key {
                        RefKey::Auid(id) => id.to_string(),
                        RefKey::MobId(id) => id.to_string(),
                    };
                    format!("w:{weakref_index}:{key_pid}:{key}")
                }
                PropertyValue::Opaque(bytes) => format!("d:{}", describe_stream(bytes)),
                other => panic!("this test does not know how to describe {other:?}"),
            };
            format!("{}:{}:{}", property.pid, property.format.to_code(), value)
        })
        .collect::<Vec<_>>()
        .join("|")
}

/// Every object in both files, with every property, against `pyaaf2`.
///
/// This walks the object tree the same way pyaaf2 does — following strong
/// references, their vectors and their sets — and compares the path, class and
/// full property list of each object it reaches. Getting the same objects in
/// the same places means the reference resolution matches; getting the same
/// property lists means the property stream and index parsing match.
#[test]
fn matches_pyaaf2_on_every_object() {
    for (fixture, manifest, expected_count) in [
        ("empty.aaf", "empty.objects.tsv", 359),
        ("sector_size_512.aaf", "sector_size_512.objects.tsv", 636),
    ] {
        let expected = read_objects_manifest(manifest);
        assert_eq!(expected.len(), expected_count, "{manifest}");

        let mut file = open(fixture);
        let mut walked = file.walk().expect("the object tree is walkable");
        walked.sort_by(|a, b| a.0.cmp(&b.0));

        assert_eq!(
            walked.len(),
            expected.len(),
            "{fixture}: object count differs from pyaaf2"
        );

        for (row, (path, object)) in expected.iter().zip(walked) {
            assert_eq!(&path, &row.path, "{fixture}: paths diverge");
            assert_eq!(
                object.class_id().to_string(),
                row.class_id,
                "{fixture}: {path} has the wrong class"
            );
            assert_eq!(
                describe(&mut file, &object),
                row.properties,
                "{fixture}: {path} has the wrong properties"
            );
        }
    }
}

#[test]
fn the_root_object_owns_the_header_and_the_meta_dictionary() {
    let mut file = open("empty.aaf");
    let root = file.root().expect("the root object reads");

    assert_eq!(
        root.class_id().to_string(),
        "b3b398a5-1c90-11d4-8053-080036210804"
    );
    assert_eq!(root.version(), 32);

    // Both properties are strong references, so the root owns everything.
    let children = file.children(&root).expect("children read");
    let names: Vec<_> = children
        .iter()
        .map(|(pid, child)| (*pid, file.cfb().path(child.storage()).expect("has a path")))
        .collect();
    assert_eq!(
        names,
        vec![
            (1, "/MetaDictionary-1".to_owned()),
            (2, "/Header-2".to_owned())
        ]
    );
}

/// Which storage formats these fixtures actually exercise end to end.
///
/// Six of the eight formats that occur in practice appear here. The two that
/// do not are `DataStream`, which needs a file carrying essence, and
/// `WeakRefSet`, which neither fixture happens to use; both are covered by
/// unit tests on the parser instead. If this set changes, that claim needs
/// revisiting rather than the assertion being widened.
#[test]
fn reads_the_formats_these_fixtures_use() {
    let mut seen = std::collections::BTreeSet::new();
    for fixture in ["empty.aaf", "sector_size_512.aaf"] {
        let mut file = open(fixture);
        for (_, object) in file.walk().expect("walkable") {
            for property in object.properties() {
                seen.insert(property.format);
            }
        }
    }

    assert_eq!(
        seen,
        [
            PropertyFormat::Data,
            PropertyFormat::StrongRef,
            PropertyFormat::StrongRefVector,
            PropertyFormat::StrongRefSet,
            PropertyFormat::WeakRef,
            PropertyFormat::WeakRefVector,
        ]
        .into_iter()
        .collect()
    );
}

#[test]
fn collections_name_their_members_and_their_index() {
    let mut file = open("empty.aaf");
    let root = file.root().expect("root reads");
    let header = file
        .children(&root)
        .expect("children read")
        .into_iter()
        .find(|(pid, _)| *pid == 2)
        .expect("the root owns a header")
        .1;

    let dictionary = file
        .children(&header)
        .expect("children read")
        .into_iter()
        .map(|(_, child)| child)
        .find(|child| child.class_id().to_string() == "0d010101-0101-2200-060e-2b3402060101")
        .expect("the header owns a dictionary");

    let (property, index_name) = dictionary
        .properties()
        .iter()
        .find_map(|p| match &p.value {
            PropertyValue::StrongRefSet { index_name } => Some((p.clone(), index_name.clone())),
            _ => None,
        })
        .expect("the dictionary has a set");

    assert_eq!(
        property.index_stream_name().as_deref(),
        Some(format!("{index_name} index").as_str())
    );

    // Each member lives in a storage named after the property and its key.
    let index = file.set_index(&dictionary, &property).expect("index reads");
    assert!(!index.entries.is_empty());
    for entry in &index.entries {
        let name = aaf::property::member_storage_name(&index_name, entry.local_key);
        let path = format!(
            "{}/{name}",
            file.cfb().path(dictionary.storage()).expect("path")
        );
        assert!(file.cfb().find(&path).is_some(), "{path} should exist");
        assert_eq!(entry.ref_count, 1);
        assert!(matches!(entry.key, RefKey::Auid(_)));
    }
}

#[test]
fn mob_ids_round_trip_through_their_urn_form() {
    let urn = "urn:smpte:umid:060a2b34.01010101.01010f00.13000000.\
               060e2b34.7f7f2a80.4fa5c20f.4e301e50";
    let id: aaf::MobId = urn.parse().expect("parses");

    assert_eq!(id.to_string(), urn);
    assert_eq!(id.length(), 0x13);
    assert_eq!(id.instance(), [0, 0, 0]);
    assert_eq!(
        id.smpte_label(),
        [
            0x06, 0x0a, 0x2b, 0x34, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x0f, 0x00
        ]
    );
    // The label marks a material number stored with its halves swapped, as
    // Avid stores it and pyaaf2 parses it, so what is stored is the second
    // half of the text first.
    assert_eq!(
        id.material().to_string(),
        "4fa5c20f-4e30-1e50-060e-2b347f7f2a80"
    );
    assert_eq!(aaf::MobId::from_bytes(id.to_bytes()), id);

    assert!(aaf::MobId::NIL.is_nil());
    assert!("not a mobid".parse::<aaf::MobId>().is_err());
}
